import{_ as o,o as d,c as e,a5 as a}from"./chunks/framework.BEZBAInb.js";const k=JSON.parse('{"title":"KonadoScript エディター","description":"","frontmatter":{"title":"KonadoScript エディター","order":5},"headers":[],"relativePath":"ja/latest/tutorial/core/ks-editor-highlighter.md","filePath":"ja/latest/tutorial/core/ks-editor-highlighter.md","lastUpdated":1788455378000}'),i={name:"ja/latest/tutorial/core/ks-editor-highlighter.md"};function c(r,t,s,l,n,h){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="godot-内蔵-konadoscript-エディター" tabindex="-1">Godot 内蔵 KonadoScript エディター <a class="header-anchor" href="#godot-内蔵-konadoscript-エディター" aria-label="Permalink to &quot;Godot 内蔵 KonadoScript エディター&quot;">​</a></h1><p>Konado プラグインを有効にした後、ファイルシステムドックで <code>.ks</code> ファイルをダブルクリックすると、<code>.gd</code> ファイルと同じように Godot のスクリプトワークスペースで開きます。KonadoScript は下部ドックではなく、Godot 標準のコードエディターとドキュメントタブを使用します。</p><h2 id="編集機能" tabindex="-1">編集機能 <a class="header-anchor" href="#編集機能" aria-label="Permalink to &quot;編集機能&quot;">​</a></h2><ul><li>Godot のスクリプトタブで <code>.ks</code>、<code>.gd</code>、その他のスクリプトをまとめて編集</li><li><code>.ks</code> の編集中は左上のスクリプト一覧をコンポーネント／命令ツリーに切り替える。初回表示時のコンポーネント領域と分岐領域の高さは 2:1。見出し右側のスライド式スイッチですべてのグループを展開／折りたたみでき、折りたたみ後も最上位カテゴリは残る。項目を選ぶと対応する文を挿入し、左下のメンバーアウトラインは分岐移動用として維持</li><li>「オンラインドキュメント」からエディター言語に対応する <code>2.4 LTS</code> または <code>latest</code> 文書を開く。<code>.ks</code> の編集中は KonadoScript 非対応の Godot API ヘルプ検索を非表示にし、他のスクリプト言語へ切り替えると Godot 本来の表示へ復元</li><li>現在のシナリオに言語バリアントがある場合は、「オンラインドキュメント」の隣にある選択欄からデフォルト版と検出済みのローカライズ版を直接切り替え</li><li>元に戻す・やり直し、未保存状態、外部変更、終了確認を Godot が一括管理</li><li>スクリプトエディターの検索と置換、行移動、ズーム、ブックマーク、ショートカットを利用</li><li>ファイルシステムの「作成」メニューから、有効な初期内容を含む KonadoScript を新規作成</li><li>メンバーアウトラインに <code>branch</code> 宣言を表示。分岐、変数、シグナルで定義へ移動、参照検索、安全な名前変更を利用可能</li><li>背景、アクター、状態、モーション、BGM、効果音、ボイス、カメラ設定、<code>jump</code> パスを Ctrl キー（macOS では Command キー）を押しながらクリックし、実際のシーン、リソース、または KonadoScript を開く。候補が複数ある場合は選択リストを表示</li><li>命令やリソース識別子にカーソルを合わせると、シグネチャ、用途、解決先パス、未解決状態を表示。実在する移動先がある範囲だけをリンクとして下線表示</li><li>コンテキストメニューから文書または選択範囲の整形、修正候補、定義へ移動、参照検索、安全な名前変更を実行。ファイルをまたぐリソース名変更は変更プレビューを先に表示</li><li>条件ブロックと全画面テキストブロックを Godot のインデント設定に従って自動整形</li><li>元の <code>.ks</code> に直接保存し、リソースローダーがコンパイルした実行時用 <code>KonadoShot</code> を更新</li></ul><h2 id="ハイライトとコード補完" tabindex="-1">ハイライトとコード補完 <a class="header-anchor" href="#ハイライトとコード補完" aria-label="Permalink to &quot;ハイライトとコード補完&quot;">​</a></h2><p><code>KonadoScriptSyntaxHighlighter</code> は Godot の <code>EditorSyntaxHighlighter</code> を基に実装され、プラグイン起動時にスクリプトエディターへ登録されます。ハイライトとコード補完は <code>KonadoScriptLanguageCatalog</code> を共有し、有効なキーワードはパーサーの <code>KonadoScriptToken.KEYWORDS</code> を基準とします。自動テストが両者の整合性を確認します。</p><p>補完は命令、サブコマンド、挿入可能なステートメントテンプレートに加え、現在の命令で使用できる 2.8 の名前付き引数を提示し、入力済みの引数は重複して提案しません。さらにプロジェクト内の KonadoScript パス、キャラクター、状態、アクション、背景、音声、カメラを索引化します。状態とカスタムモーションは選択したアクターに合わせて絞り込まれ、空白を含む引用テキストの後でもボイスを補完できます。現在のドキュメント内の分岐、変数、シグナルも即座に候補へ追加します。名前付き引数には専用のハイライトが付き、型、範囲、競合、ID の重複は正式なコンパイラーが最終確認します。ハイライト用の式は初回だけコンパイルされ、各行には色が変わる位置だけを記録します。</p><p>デフォルトのハイライトリソース：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>res://addons/konado/editor/script_editor/konado_script_highlighter.tres</span></span></code></pre></div><p>他の <code>CodeEdit</code> でもハイライターを直接利用できます。</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_syntax_highlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KonadoScriptSyntaxHighlighter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span></code></pre></div><h2 id="ライブ診断" tabindex="-1">ライブ診断 <a class="header-anchor" href="#ライブ診断" aria-label="Permalink to &quot;ライブ診断&quot;">​</a></h2><p>入力を少し止めると、Godot は KonadoScript 言語ブリッジを通じて、実行時用 <code>KonadoShot</code> を生成せずに字句・構文・意味解析を実行します。エラーと警告は対象の行とスクリプトエディター内蔵の問題パネルに表示され、Godot エディターの言語に応じて中国語または英語になります。複数行の独立したエラーを一度に報告し、余分な引数、不正な数値や真偽値、無効なジャンプパス、未知のリソース ID、欠落した対象ファイル、アクターのライフサイクル、ローカライズ版の構造を検査します。不正な入力でライブ解析が停止することはありません。</p><p>エラー範囲にカーソルを合わせると、内容に応じて幅と高さが変わる診断カードが表示されます。診断には可能性の高い順に最大 3 個の「試す」候補を表示できます。判断が必要な選択肢は「安全なクイック修正をすべて適用」の対象外です。自動編集できない問題にはリソース設定またはドキュメントへの入口が表示されます。修正は 1 回の取り消し可能な操作として適用され、キャレット、選択範囲、複数キャレット、折りたたみ、スクロール位置を保持します。</p><p>問題をクリックすると該当位置へ移動できます。既存ファイルに構文エラーがあっても、スクリプトエディターで開いて修正できます。保存後はリソースローダーが正式なコンパイルを行うため、ライブ診断は最終的な読み込み結果の代わりにはなりません。</p><h2 id="実行時デバッグ" tabindex="-1">実行時デバッグ <a class="header-anchor" href="#実行時デバッグ" aria-label="Permalink to &quot;実行時デバッグ&quot;">​</a></h2><p>Godot のブレークポイントで KonadoScript の実行を制御できます。ブレークポイントに到達すると対応する <code>.ks</code> 行が開き、現在のショット、ノード、永続変数、一時変数が表示されます。デバッガータブには続行、ステップ、次の行で一時停止の操作があります。リリースエクスポートではエディターのデバッグセッションは有効になりません。</p><h2 id="ショートカット" tabindex="-1">ショートカット <a class="header-anchor" href="#ショートカット" aria-label="Permalink to &quot;ショートカット&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>Windows / Linux</th><th>macOS</th></tr></thead><tbody><tr><td>保存</td><td><code>Ctrl+S</code></td><td><code>Command+S</code></td></tr><tr><td>現在のタブを閉じる</td><td><code>Ctrl+W</code></td><td><code>Command+W</code></td></tr><tr><td>検索</td><td><code>Ctrl+F</code></td><td><code>Command+F</code></td></tr><tr><td>検索と置換</td><td><code>Ctrl+H</code></td><td><code>Command+Option+F</code></td></tr><tr><td>行へ移動</td><td><code>Ctrl+L</code></td><td><code>Command+L</code></td></tr></tbody></table>',19)])])}const g=o(i,[["render",c]]);export{k as __pageData,g as default};
